  {
    SELECT ?country (AVG(?lifespan) AS ?avgLifespan) WHERE {
      ?person wdt:P31 wd:Q5 ;
              wdt:P27 ?country ;
              wdt:P569 ?birth ;
              wdt:P570 ?death .
      BIND(YEAR(?death) - YEAR(?birth) AS ?lifespan)
      FILTER(?lifespan > 0 && ?lifespan < 130)
