SELECT ?award ?awardLabel (ROUND(100.0 * ?females / ?total) AS ?percentageFemale) WHERE {
  {
    SELECT ?award (COUNT(DISTINCT ?recipient) AS ?total) WHERE {
      ?recipient wdt:P166 ?award .
      ?recipient wdt:P21 ?gender .
      ?award wdt:P31/wdt:P279* wd:Q618779 .
    }
    GROUP BY ?award
    HAVING (COUNT(DISTINCT ?recipient) > 20)
  }
  {
    SELECT ?award (COUNT(DISTINCT ?recipient) AS ?females) WHERE {
      ?recipient wdt:P166 ?award .
      ?recipient wdt:P21 wd:Q6581072 .
      ?award wdt:P31/wdt:P279* wd:Q618779 .
    }
    GROUP BY ?award
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?percentageFemale)
LIMIT 100

