SELECT DISTINCT ?country1 ?country1Label ?capital1 ?capital1Label ?country2 ?country2Label ?capital2 ?capital2Label ?distance
WHERE {
  ?country1 wdt:P31 wd:Q6256 ;
            wdt:P36 ?capital1 .
  ?country2 wdt:P31 wd:Q6256 ;
            wdt:P36 ?capital2 .

  FILTER(STR(?country1) < STR(?country2))

  # The two countries do NOT share a border
  FILTER NOT EXISTS { ?country1 wdt:P47 ?country2 . }
  FILTER NOT EXISTS { ?country2 wdt:P47 ?country1 . }

  ?capital1 wdt:P625 ?coord1 .
  ?capital2 wdt:P625 ?coord2 .

  BIND(geof:distance(?coord1, ?coord2) AS ?distance)
  FILTER(?distance < 200)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance
LIMIT 100

