SELECT ?institution ?institutionLabel WHERE {
  # Get all #vBIB conferences
  {
    SELECT (COUNT(DISTINCT ?conf) AS ?totalConf) WHERE {
      ?conf wdt:P31 wd:Q2020153 .
      ?conf rdfs:label ?confLabel .
      FILTER(CONTAINS(LCASE(?confLabel), "vbib"))
    }
  }

  {
    SELECT ?institution (COUNT(DISTINCT ?conf) AS ?contribCount) WHERE {
      ?conf wdt:P31 wd:Q2020153 .
      ?conf rdfs:label ?confLabel .
      FILTER(CONTAINS(LCASE(?confLabel), "vbib"))
      ?contribution wdt:P179 ?conf .
      ?contribution wdt:P859 ?institution .
    }
    GROUP BY ?institution
  }

  FILTER(?contribCount = ?totalConf)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

