            p:P39 ?positionStatement .
  ?positionStatement ps:P39 ?position .
  ?position wdt:P361 ?cabinet .
  ?cabinet wdt:P31 wd:Q5057319 .
  OPTIONAL { ?cabinet wdt:P571 ?inception . }
  FILTER(!BOUND(?inception) || YEAR(?inception) >= 1990)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
