SELECT ?museum ?museumLabel ?location ?distance WHERE {
  # Set your current location coordinates here (example: Berlin)
  BIND("Point(13.4050 52.5200)"^^geo:wktLiteral AS ?currentLocation)

  ?museum wdt:P31/wdt:P279* wd:Q33506 ;   # instance of museum (or subclass)
          wdt:P625 ?location .

  BIND(geof:distance(?currentLocation, ?location) AS ?distance)
  FILTER(?distance <= 20)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance

