  ?person wdt:P31 wd:Q5 ;
          wdt:P569 ?dob ;
          wdt:P106 ?occupation .
  FILTER(MONTH(?dob) = 1)
  BIND(YEAR(?dob) AS ?year)
  FILTER((?year % 4 = 0 && ?year % 100 != 0) || (?year % 400 = 0))
